import contextlib,io,json,pathlib,sys
from fractions import Fraction as Q
source=pathlib.Path(sys.argv[1]).read_text(encoding='utf-8');ns={'__name__':'checked_source'}
exec(compile(source,sys.argv[1],'exec'),ns)
valid=[('exact',(0,),Q(0)),('cos_num',(0,0,0),Q(0)),('cos_num',(5,3,4),Q(0)),('cos_law',(3,4,5),Q(4,5)),('gamma',(0,),Q(1)),('gamma',(-2,),Q(-5,3)),('block_trace',(0,),Q(4)),('block_trace',(Q(-1,2),),Q(16,3))]
for name,args,expected in valid:
 actual=ns[name](*args)
 if type(actual) is not Q or actual!=expected:raise AssertionError(('wrong exact value',name,str(actual),type(actual).__name__,str(expected)))
invalid=[True,0.1,'1/2',1j,None,object()];rejected=0
def refuses(name,args,expected_exception):
 try:ns[name](*args)
 except Exception as exc:
  if not isinstance(exc,expected_exception):raise AssertionError(('wrong exception',name,type(exc).__name__,expected_exception.__name__)) from exc
 else:raise AssertionError(('invalid input accepted',name,[repr(v) for v in args]))
for name,arity in [('exact',1),('cos_num',3),('cos_law',3),('gamma',1),('block_trace',1)]:
 for position in range(arity):
  for value in invalid:
   args=[Q(2)]*arity;args[position]=value;refuses(name,args,TypeError);rejected+=1
for name,args in [('cos_law',(1,0,3)),('cos_law',(1,2,0)),('gamma',(1,)),('gamma',(-1,)),('block_trace',(1,)),('block_trace',(-1,))]:
 refuses(name,args,ValueError);rejected+=1
output=io.StringIO()
with contextlib.redirect_stdout(output):ns['main']()
print(json.dumps(dict(optimize=sys.flags.optimize,valid_cases=len(valid),rejection_controls=rejected,main_output=output.getvalue())))
